import { useEffect, useState } from "react";
import { getAllMatches } from "../api";
import toast from "react-hot-toast";

export default function MatchView() {
  const [matches, setMatches] = useState([]);

  useEffect(() => {
    const fetchMatches = async () => {
      try {
        const res = await getAllMatches();
        setMatches(res);
      } catch (err) {
        toast.error("Failed to load match data");
      }
    };
    fetchMatches();
  }, []);

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <h1 className="text-3xl font-bold mb-6">Match Overview</h1>
      {matches.length === 0 ? (
        <p className="text-yellow-600">No matches yet.</p>
      ) : (
        <ul className="space-y-4">
          {matches.map((pair, idx) => (
            <li key={idx} className="bg-white text-black p-4 rounded shadow">
              <strong>Student:</strong> {pair.student.name}  
              <br />
              <strong>→ Matched with Tutor:</strong> {pair.tutor?.name || "No tutor"}
              <br />
              <strong>Contact:</strong> {pair.tutor?.contact_info || "N/A"}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
